/**
 * Ensure TypeScript recognizes static image imports (e.g. ThreeWill footer logo).
 * Heft/webpack emit a URL string for these modules at build time.
 */
declare module '*.png' {
  const content: string;
  export default content;
}

declare module '*.jpg' {
  const content: string;
  export default content;
}

declare module '*.jpeg' {
  const content: string;
  export default content;
}

declare module '*.gif' {
  const content: string;
  export default content;
}

declare module '*.svg' {
  const content: string;
  export default content;
}
